package com.retro.t9;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.view.inputmethod.InputMethodManager;import android.text.InputType;import java.util.*;
public class SetupActivity extends Activity {
 LinearLayout root;EditText practice;
 void button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setOnClickListener(v->action.run());root.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 void label(String text){TextView v=new TextView(this);v.setText(text);v.setTextColor(0xffd9edff);v.setTextSize(14);v.setPadding(10,10,10,10);root.addView(v);}
 public void onCreate(Bundle state){super.onCreate(state);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(10,10,10,10);root.setBackgroundColor(0xff07192d);scroll.addView(root);setContentView(scroll);label("ORBIT T9 • Built into Retro Orbit");int imported=importWords();if(imported>=0)label("Personal words preserved: "+getSharedPreferences("dictionary",0).getAll().size());button("1. Enable keyboard",()->startActivity(new Intent(android.provider.Settings.ACTION_INPUT_METHOD_SETTINGS)));button("2. Choose keyboard",()->((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showInputMethodPicker());label("2–9 Type • Left/Right Alternatives\n0 Accept + space • Center Accept\nClear Delete • 1 Punctuation\n# T9 / abc / 123 • * Case\nHold # Switch keyboard");practice=new EditText(this);practice.setHint("Practice here — nothing is sent");practice.setTextColor(0xffeefaff);practice.setHintTextColor(0xff8ba6bf);practice.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);practice.setMinLines(3);root.addView(practice,new LinearLayout.LayoutParams(-1,-2));button("Clear practice field",()->practice.setText(""));button("Add a personal word",this::addWord);button("Personal dictionary",this::dictionary);button("Test number field",()->testField(true));button("Test private field",()->testField(false));button("About and dictionary credits",()->new AlertDialog.Builder(this).setTitle("Retro Orbit keyboard 1.1").setMessage("Offline English keypad input. No typing logs or uploads. The combined launcher uses internet for weather. Personal words stay in this app and are never learned from password/private fields. Frequency data by Hermit Dave, FrequencyWords / OpenSubtitles 2018, CC BY-SA 4.0. Source: github.com/hermitdave/FrequencyWords. Keyboard is an early device-test build.").setPositiveButton("OK",null).show());}
 int importWords(){android.content.SharedPreferences state=getSharedPreferences("keyboard_migration",0);if(state.getBoolean("done",false))return 0;try(android.database.Cursor cursor=getContentResolver().query(android.net.Uri.parse("content://com.retro.t9.dictionary/words"),null,null,null,null)){if(cursor==null)return -1;android.content.SharedPreferences personal=getSharedPreferences("dictionary",0);android.content.SharedPreferences.Editor edit=personal.edit();int count=0;while(cursor.moveToNext()){String word=cursor.getString(0);int frequency=cursor.getInt(1);if(Lexicon.valid(word)){edit.putInt(word,Math.max(personal.getInt(word,0),frequency));count++;}}if(!edit.commit())return -1;state.edit().putBoolean("done",true).apply();return count;}catch(Exception ignored){return -1;}}
 void addWord(){EditText word=new EditText(this);word.setHint("Use abc mode to spell a new word");word.setSingleLine();new AlertDialog.Builder(this).setTitle("Personal word").setView(word).setPositiveButton("Add",(d,n)->{String w=word.getText().toString().trim().toLowerCase(Locale.ROOT);if(Lexicon.valid(w)){getSharedPreferences("dictionary",0).edit().putInt(w,10).apply();Toast.makeText(this,"Added "+w,0).show();}else Toast.makeText(this,"Use English letters and optional apostrophes",0).show();}).setNegativeButton("Back",null).show();}
 void dictionary(){java.util.ArrayList<String> words=new java.util.ArrayList<>(getSharedPreferences("dictionary",0).getAll().keySet());Collections.sort(words);if(words.isEmpty()){new AlertDialog.Builder(this).setMessage("No personal words yet. Accepted words are learned locally.").setPositiveButton("OK",null).show();return;}new AlertDialog.Builder(this).setTitle("Select a word to forget").setItems(words.toArray(new String[0]),(d,n)->{getSharedPreferences("dictionary",0).edit().remove(words.get(n)).apply();Toast.makeText(this,"Word forgotten",0).show();}).setNegativeButton("Back",null).show();}
 void testField(boolean number){EditText field=new EditText(this);field.setInputType(number?InputType.TYPE_CLASS_NUMBER:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);new AlertDialog.Builder(this).setTitle(number?"Number test":"Private test — not learned").setView(field).setPositiveButton("Close",null).show();}
}
